import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/ViewSales.css";

const ViewSales = () => {
  const userId = sessionStorage.getItem("userId");
  const [sales, setSales] = useState([]);
  const [payoutTotal, setPayoutTotal] = useState(0);
  const [paidAmount, setPaidAmount] = useState(null);

  useEffect(() => {
    const fetchSales = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/sales/${userId}`);
        const data = await res.json();
        setSales(data);
        const total = data.reduce((sum, sale) => sum + parseFloat(sale.price), 0);
        setPayoutTotal(total);
      } catch (err) {
        console.error("Failed to load sales:", err);
      }
    };
    fetchSales();
  }, [userId]);

  const handlePayout = () => {
    const payout = (payoutTotal * 0.95).toFixed(2); // 5% fee
    setPaidAmount(payout);
    setPayoutTotal(0);
  };

  return (
    <>
      <Navbar />
      <div className="viewsales-container">
        <h2 className="viewsales-heading">Your Sales</h2>

        <div className="viewsales-list">
          {sales.map((sale) => (
            <div key={sale.id} className="viewsales-card">
              <img src={sale.image} alt={sale.title} className="viewsales-image" />
              <div className="viewsales-info">
                <h4>{sale.title}</h4>
                <p>${sale.price}</p>
              </div>
            </div>
          ))}
        </div>

        <div className="viewsales-payout">
          <h3>Total Pending Payout: ${payoutTotal.toFixed(2)}</h3>
          <button onClick={handlePayout} className="viewsales-payout-btn">
            💸 Payout Now
          </button>
          {paidAmount && (
            <div className="viewsales-paid-alert">
              <p>You got paid: <strong>${paidAmount}</strong> (after 5% fee)</p>
            </div>
          )}
        </div>
      </div>
      <Footer />
    </>
  );
};

export default ViewSales;
